import React, {FC} from 'react';
import './CatalogItems.scss';
import SortMenu from "../../entities/SortMenu/SortMenu";
import CountPrice from "../../common/CountPrice/CountPrice";
import FilterMenu from "../../entities/FilterMenu/FilterMenu";
import {IReminder} from "../../../interfaces/reminderInterfaces";

const reminders: IReminder[] = [
    {
        id: 1,
        title: "Title 1",
        description: "Description 1",
        price: 100,
        dueDate: "2021-10-10",
        lastUpdated: "2021-10-10"
    },
    {
        id: 2,
        title: "Title 2",
        description: "Description 2",
        price: 200,
        dueDate: "2021-10-10",
        lastUpdated: "2021-10-10"
    },
    {
        id: 3,
        title: "Title 3",
        description: "Description 3",
        price: 300,
        dueDate: "2021-10-10",
        lastUpdated: "2021-10-10"
    }
]

const CatalogItems: FC = () => {
    return (
        <section className={"main-container"}>
            <div className={'menu'}>
                <SortMenu/>
                <hr/>
                <FilterMenu/>
                <hr/>
                <CountPrice/>
            </div>
            <div className={"reminders-container"} id="reminders-container">

            </div>
        </section>
    );
};

export default CatalogItems;
